#!/usr/bin/env bash
# caelestia4: save the current monitor setup (after the settings app's "Keep these settings?" confirmation) to
# ~/.config/hypr/monitors.lua, one hl.monitor() per connected output, from `hyprctl monitors -j`.
set -euo pipefail
out="${XDG_CONFIG_HOME:-$HOME/.config}/hypr/monitors.lua"
[[ -f "$out" ]] && cp "$out" "$out.bak"
hyprctl monitors -j | jq -r '
  "-- Generated by the settings app (Display). Previous version: monitors.lua.bak",
  (.[] | "-- \(.description)\nhl.monitor({\n    output = \"\(.name)\",\n    mode = \"\(.width)x\(.height)@\(.refreshRate | . * 100 | round / 100)\",\n    position = \"\(.x)x\(.y)\",\n    scale = \(.scale),\n    transform = \(.transform)\n})")
' > "$out.tmp"
mv "$out.tmp" "$out"
